-- Champion image column + base champion attribute seed
-- Scope:
--   1) ensure image_url column exists
--   2) upsert champion base attributes (name/image_url/roles/tier/rates)
-- champion_stat_profile score attributes are maintained in:
--   src/main/java/com/LOLCAA/domain/sql/champion_attribute_fill.sql
ALTER TABLE champion
    ADD COLUMN IF NOT EXISTS image_url VARCHAR(255);

-- Full champion seed (official Data Dragon)
-- Version: 14.24.1
-- Safe to re-run (UPSERT)
ON CONFLICT (id) DO UPDATE SET
                               name = EXCLUDED.name,
                               image_url = EXCLUDED.image_url,
                               primary_role = EXCLUDED.primary_role,
                               secondary_role = EXCLUDED.secondary_role,
                               tier = EXCLUDED.tier,
                               pick_rate = EXCLUDED.pick_rate,
                               win_rate = EXCLUDED.win_rate;